import{f as t,o as a,c as o,a6 as r}from"./chunks/framework.Dd1qhYRL.js";const m=JSON.parse('{"title":"noorm sql repl","description":"","frontmatter":{},"headers":[],"relativePath":"cli/sql-repl.md","filePath":"cli/sql-repl.md"}'),s={name:"cli/sql-repl.md"};function i(d,e,l,n,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="noorm-sql-repl" tabindex="-1">noorm sql repl <a class="header-anchor" href="#noorm-sql-repl" aria-label="Permalink to “noorm sql repl”">​</a></h1><p>Open the TUI directly on the SQL terminal, against the active config or the one you name.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The terminal opens with the query box focused. <code>Enter</code> runs the query and <code>Esc</code> backs out. <a href="/tui.html#sql-terminal">The TUI page</a> lists the keys, and <a href="/guide/database/terminal.html">the SQL terminal guide</a> covers history, result browsing, and cancel.</p><h2 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to “Flags”">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--config &lt;name&gt;</code>, <code>-c &lt;name&gt;</code></td><td>Make this config the active one, then launch. The switch is saved, so it outlasts the session</td></tr><tr><td><code>--yes</code>, <code>-y</code></td><td>Accepted only to refuse: see below</td></tr></tbody></table><h2 id="where-does-it-refuse-to-run" tabindex="-1">Where does it refuse to run? <a class="header-anchor" href="#where-does-it-refuse-to-run" aria-label="Permalink to “Where does it refuse to run?”">​</a></h2><p>A REPL is interactive, so <code>--yes</code> and <code>NOORM_YES</code> cannot make it run unattended.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td><code>--yes</code>, <code>-y</code>, or <code>NOORM_YES=1</code></td><td><code>Error: noorm sql repl is interactive only.</code> with <code>noorm sql query &quot;SELECT 1&quot;</code> and <code>noorm sql query --file query.sql</code> as the headless routes. Exit 2</td></tr><tr><td>No terminal on stdin</td><td><code>Error: noorm sql repl requires an interactive terminal.</code>, exit 2</td></tr><tr><td><code>--config</code> names a config that does not exist</td><td><code>Error: Config not found: &lt;name&gt;</code>, exit 2</td></tr><tr><td>State cannot be decrypted</td><td><code>Error: &lt;message&gt;</code>, exit 1</td></tr></tbody></table><p>Use <a href="/cli/sql.html"><code>noorm sql query</code></a> for one-shot SQL in scripts and CI. History from the terminal is what <a href="/cli/sql.html#sql-history"><code>noorm sql history</code></a> reads.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/cli/sql.html"><code>noorm sql</code></a>: one-shot queries and history</li><li><a href="/tui.html">The TUI</a>: keys for every screen</li></ul>',12)])])}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
